package com.nbi.secure.security;

import org.springframework.stereotype.Service;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

@Service
public class RateLimiter {
    private final ConcurrentMap<String, AtomicInteger> counts = new ConcurrentHashMap<>();
    private static final int MAX = 100; // per window (simplified)

    public boolean allow(String client) {
        AtomicInteger c = counts.computeIfAbsent(client, k -> new AtomicInteger());
        return c.incrementAndGet() <= MAX; // false → caller returns 429
    }
}
