package com.nbi.secure.audit;

import org.slf4j.*;
import org.springframework.stereotype.Service;

@Service
public class AuditService {
    private static final Logger log = LoggerFactory.getLogger(AuditService.class);

    // Logs WHO/WHAT/WHEN; NEVER logs tokens, passwords, or full account secrets.
    public void record(String user, String action, String detail) {
        log.info("AUDIT user={} action={} detail={}", mask(user), action, detail);
    }
    private String mask(String s) { // mask all but last 2 chars
        return s == null || s.length() < 3 ? "***" : "***" + s.substring(s.length() - 2);
    }
}
